import { randomUUID } from 'node:crypto';
import { lstat, readdir, realpath, rename, rm, rmdir } from 'node:fs/promises';
import { join } from 'node:path';
import { atomicWrite, cleanTemporaryFiles } from './writer';
import { hasCode, safeDirectory } from './paths';
import { OwnerLock } from './owner-lock';
import { updateProjectGitignore } from './gitignore';

const LOCAL_IGNORES =
  '# Machine-local Oxytocin files. Generated by Oxytocin.\n/code-map/cache/\n/code-map/manifest.json\n/code-map/owner.lock\n/code-map/owner.lock.guard/\n/learnings/local/\n*.tmp-*\n';

export async function prepareOxyDirectory(options: {
  root: string;
  mode: 'project' | 'worktree';
  ignoreInGit: boolean;
  gitPath: string;
  removeGitignoreEntry: boolean;
  app: string;
}) {
  const oxy = await safeDirectory(options.root, ['.oxy']);
  const directory = await safeDirectory(options.root, ['.oxy', 'code-map']);
  const claim = await OwnerLock.acquire(directory, options.app);
  if (!claim.lease) return { directory, ...claim, warning: 'Updated by another Oxytocin instance' };
  try {
    await cleanTemporaryFiles(directory);
    const ignored = options.mode === 'worktree' || options.ignoreInGit;
    await atomicWrite(join(oxy, '.gitignore'), ignored ? '*\n' : LOCAL_IGNORES);
    await atomicWrite(
      join(oxy, 'README.md'),
      `This folder is created by Oxytocin. The Code Map is regenerable; learnings are durable findings. ${ignored ? 'It is ignored by Git. ' : ''}Rebuild and Delete map data preserve learnings. Use Forget all learnings to remove them.\n`,
    );
    let warning: string | null;
    try {
      warning = await updateProjectGitignore(options);
    } catch (error) {
      warning = error instanceof Error ? error.message : String(error);
    }
    return { directory, ...claim, warning };
  } catch (error) {
    await claim.lease.dispose();
    throw error;
  }
}

/** Map data has a separate lifetime from learnings and any other .oxy consumer. */
export async function deleteMapData(root: string, existingLease?: OwnerLock): Promise<void> {
  const directory = await safeDirectory(root, ['.oxy', 'code-map'], false);
  const canonicalRoot = await realpath(root);
  const lease = existingLease ?? (await OwnerLock.acquire(directory, 'Oxytocin')).lease;
  if (!lease) throw new Error('Updated by another Oxytocin instance');
  const retired = join(canonicalRoot, '.oxy', `code-map.tmp-${randomUUID()}`);
  try {
    // The rename separates old data from a new instance configuring the same checkout.
    await lease.retire(() => rename(join(canonicalRoot, '.oxy', 'code-map'), retired));
    await rm(retired, { recursive: true, force: true });
  } finally {
    await lease.dispose();
  }
  const oxy = await safeDirectory(root, ['.oxy'], false);
  const remaining = await readdir(oxy);
  if (
    remaining.every((entry) => entry === '.gitignore' || entry === 'README.md') &&
    !(await lstat(join(canonicalRoot, '.oxy'))).isSymbolicLink()
  ) {
    for (const name of remaining) await rm(join(oxy, name), { force: true });
    // rmdir is atomic and refuses a new checkout or learning directory created since readdir.
    await rmdir(oxy).catch((error: unknown) => {
      if (!hasCode(error, 'ENOTEMPTY') && !hasCode(error, 'EEXIST') && !hasCode(error, 'ENOENT')) throw error;
    });
  }
}
